package com.finsight.service; import com.finsight.domain.*; import org.springframework.stereotype.Service; @Service public class RiskAssessmentService {public record Result(int score,String level,double leverage){} public Result assess(CreditApplication a){Customer c=a.getCustomer();int s=50;if(c.getAnnualRevenue()>300000000)s+=10;if(c.getEbitda()>50000000)s+=10;if(c.getCashBalance()>50000000)s+=10;s+=Math.round(c.getPaymentHistoryScore()/10f);double lev=c.getEbitda()>0?c.getTotalDebt()/c.getEbitda():99;if(lev>4)s-=20;else if(lev>2.5)s-=10;if("Technology".equalsIgnoreCase(c.getIndustry()))s+=3;s=Math.max(0,Math.min(100,s));String l=s>=80?"LOW":s>=60?"MEDIUM":s>=40?"HIGH":"VERY_HIGH";return new Result(s,l,lev);}}
